package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"sync"
)

const tasksFile = "tasks.json"

// Task represents a single todo item.
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Global variable to hold tasks and a mutex for safe concurrent access
var (
	tasks []Task
	mu    sync.Mutex
	nextID int
)

func init() {
	loadTasks()
}

// loadTasks loads tasks from the tasks.json file.
func loadTasks() {
	mu.Lock()
	defer mu.Unlock()

	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			tasks = []Task{}
			nextID = 1
			return
		}
		// In a real application, we might log this error more verbosely.
		// For this CLI, we'll just initialize an empty task list if loading fails.
		tasks = []Task{}
		nextID = 1
		return
	}

	if err := json.Unmarshal(data, &tasks); err != nil {
		tasks = []Task{}
		nextID = 1
		return
	}

	if len(tasks) > 0 {
		nextID = tasks[len(tasks)-1].ID + 1
	} else {
		nextID = 1
	}
}

// saveTasks saves the current tasks to the tasks.json file.
func saveTasks() error {
	mu.Lock()
	defer mu.Unlock()

	data, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal tasks: %w", err)
	}

	if err := ioutil.WriteFile(tasksFile, data, 0644); err != nil {
		return fmt.Errorf("failed to write tasks file: %w", err)
	}
	return nil
}

// addTask adds a new task with the given description.
func addTask(description string) Task {
	mu.Lock()
	defer mu.Unlock()

	task := Task{
		ID:          nextID,
		Description: description,
		Done:        false,
	}
	tasks = append(tasks, task)
	nextID++
	saveTasks() // Save after adding
	return task
}

// getTasks returns all tasks.
func getTasks() []Task {
	mu.Lock()
	defer mu.Unlock()
	return tasks
}

// completeTask marks a task as done by its ID.
func completeTask(id int) (Task, error) {
	mu.Lock()
	defer mu.Unlock()

	for i, task := range tasks {
		if task.ID == id {
			tasks[i].Done = true
			saveTasks() // Save after completing
			return tasks[i], nil
		}
	}
	return Task{}, fmt.Errorf("task with ID %d not found", id)
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"
)

func main() {
	// Subcommands
	addCmd := flag.NewFlagSet("add", flag.ExitOnError)
	addDescription := addCmd.String("text", "", "Description of the task")

	doneCmd := flag.NewFlagSet("done", flag.ExitOnError)
	doneID := doneCmd.Int("id", 0, "ID of the task to complete")

	listCmd := flag.NewFlagSet("list", flag.ExitOnError)

	if len(os.Args) < 2 {
		printError("invalid arguments", 42)
	}

	switch os.Args[1] {
	case "add":
		addCmd.Parse(os.Args[2:])
		if *addDescription == "" {
			printError("task description cannot be empty", 42)
		}
		task := addTask(*addDescription)
		printJSON(map[string]interface{}{"id": task.ID, "status": "added"})

	case "list":
		listCmd.Parse(os.Args[2:])
		tasks := getTasks()
		// Filter for pending tasks only
		pendingTasks := []Task{}
		for _, task := range tasks {
			if !task.Done {
				pendingTasks = append(pendingTasks, task)
			}
		}
		printJSON(pendingTasks)

	case "done":
		doneCmd.Parse(os.Args[2:])
		if *doneID == 0 {
			printError("task ID cannot be zero", 42)
		}
		task, err := completeTask(*doneID)
		if err != nil {
			printError(err.Error(), 1)
		}
		printJSON(map[string]interface{}{"id": task.ID, "status": "completed"})

	default:
		printError("unknown command", 42)
	}
}

func printJSON(data interface{}) {
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ") // Pretty print for readability
	if err := encoder.Encode(data); err != nil {
		// Fallback to plain error if JSON encoding fails
		fmt.Fprintf(os.Stderr, "{\"error\": \"failed to encode JSON: %v\"}\n", err)
		os.Exit(1)
	}
}

func printError(message string, exitCode int) {
	errorOutput := map[string]string{"error": message}
	encoder := json.NewEncoder(os.Stdout)
	if err := encoder.Encode(errorOutput); err != nil {
		// Fallback to plain error if JSON encoding fails
		fmt.Fprintf(os.Stderr, "{\"error\": \"failed to encode JSON error: %v\"}\n", err)
	}
	os.Exit(exitCode)
}

