)

func TestMain(m *testing.M) {
	// Setup: Ensure a clean tasks.json before tests run
	os.Remove(tasksFile)

	// Run tests
	exitCode := m.Run()

	// Teardown: Clean up tasks.json after tests
	os.Remove(tasksFile)
	os.Exit(exitCode)
}

func TestLoadAndSaveTasks(t *testing.T) {
	// Ensure tasks list is empty before starting
	mu.Lock()
	tasks = []Task{}
	nextID = 1
	mu.Unlock()

	// Add a task directly to the tasks slice (bypassing addTask for testing load/save)
	mu.Lock()
	tasks = append(tasks, Task{ID: 1, Description: "Test task 1", Done: false})
	nextID = 2
	mu.Unlock()

	err := saveTasks()
	if err != nil {
		t.Fatalf("saveTasks failed: %v", err)
	}

	// Clear in-memory tasks to ensure load reads from file
	mu.Lock()
	tasks = []Task{}
	nextID = 1
	mu.Unlock()

	loadTasks()

	mu.Lock()
	defer mu.Unlock()

	if len(tasks) != 1 {
		t.Fatalf("Expected 1 task after loading, got %d", len(tasks))
	}

	expectedTask := Task{ID: 1, Description: "Test task 1", Done: false}
	if !reflect.DeepEqual(tasks[0], expectedTask) {
		t.Errorf("Loaded task mismatch. Expected %+v, got %+v", expectedTask, tasks[0])
	}

	if nextID != 2 {
		t.Errorf("Expected nextID to be 2, got %d", nextID)
	}
}

func TestAddTask(t *testing.T) {
	// Ensure tasks list is empty before starting
	mu.Lock()
	tasks = []Task{}
	nextID = 1
	mu.Unlock()

	description := "Buy groceries"
	task := addTask(description)

	if task.ID != 1 {
		t.Errorf("Expected task ID to be 1, got %d", task.ID)
	}
	if task.Description != description {
		t.Errorf("Expected description %q, got %q", description, task.Description)
	}
	if task.Done != false {
		t.Errorf("Expected task to be not done, got %t", task.Done)
	}

	loadedTasks := getTasks()
	if len(loadedTasks) != 1 {
		t.Fatalf("Expected 1 task after adding, got %d", len(loadedTasks))
	}
	if loadedTasks[0].Description != description {
		t.Errorf("Loaded task description mismatch. Expected %q, got %q", description, loadedTasks[0].Description)
	}

	// Add another task to check ID increment
	description2 := "Pay bills"
	task2 := addTask(description2)

	if task2.ID != 2 {
		t.Errorf("Expected second task ID to be 2, got %d", task2.ID)
	}
}

func TestGetTasks(t *testing.T) {
	// Ensure tasks list is empty before starting
	mu.Lock()
	tasks = []Task{}
	nextID = 1
	mu.Unlock()

	addTask("Task A")
	addTask("Task B")

	loadedTasks := getTasks()

	if len(loadedTasks) != 2 {
		t.Fatalf("Expected 2 tasks, got %d", len(loadedTasks))
	}

	expectedDescriptions := []string{"Task A", "Task B"}
	for i, task := range loadedTasks {
		if task.Description != expectedDescriptions[i] {
			t.Errorf("Task description mismatch at index %d. Expected %q, got %q", i, expectedDescriptions[i], task.Description)
		}
	}
}

func TestCompleteTask(t *testing.T) {
	// Ensure tasks list is empty before starting
	mu.Lock()
	tasks = []Task{}
	nextID = 1
	mu.Unlock()

	task1 := addTask("Task to complete 1")
	addTask("Task to complete 2")

	completedTask, err := completeTask(task1.ID)
	if err != nil {
		t.Fatalf("completeTask failed: %v", err)
	}

	if completedTask.Done != true {
		t.Errorf("Expected task to be done, got %t", completedTask.Done)
	}

	loadedTasks := getTasks()
	found := false
	for _, task := range loadedTasks {
		if task.ID == task1.ID {
			found = true
			if task.Done != true {
				t.Errorf("Task in loaded list not marked as done")
			}
			break
		}
	}
	if !found {
		t.Errorf("Completed task not found in loaded list")
	}

	// Test completing a non-existent task
	_, err = completeTask(999)
	if err == nil {
		t.Errorf("Expected error when completing non-existent task, got nil")
	}
	expectedErrorMsg := "task with ID 999 not found"
	if err.Error() != expectedErrorMsg {
		t.Errorf("Expected error message %q, got %q", expectedErrorMsg, err.Error())
	}
}

